function [p, cnt] = smul(x, y, n)
  if n == 1
    p = x * y; cnt = 1;
  else
    m = ceil(n/2); a = floor(x/10^m); b = mod(x, 10^m); c = floor(y/10^m); d = mod(y, 10^m);
    [e, c1] = smul(a, c, m); [f, c2] = smul(b, d, m); [g, c3] = smul(b, c, m); [h, c4] = smul(a, d, m);
    p = 10^(2*m)*e + 10^m*(g + h) + f; cnt = c1 + c2 + c3 + c4;
  end
end

